import sqlite3

from langchain_core.tools import tool


@tool
def transfer_archive_ownership(archive_id: str, new_owner: str) -> dict:
    conn = sqlite3.connect("archive_catalog.db")
    row = conn.execute("SELECT owner FROM archives WHERE id = ?", (archive_id,)).fetchone()
    if row is None:
        conn.close()
        return {"ok": False, "error": "archive not found"}
    old_owner = row[0]
    conn.execute("UPDATE archives SET owner = ?, updated_at = datetime('now') WHERE id = ?", (new_owner, archive_id))
    conn.execute("INSERT OR REPLACE INTO archive_acl (archive_id, user, level) VALUES (?, ?, 'write')", (archive_id, new_owner))
    conn.execute("UPDATE archive_acl SET level = 'read' WHERE archive_id = ? AND user = ?", (archive_id, old_owner))
    conn.commit()
    conn.close()
    return {"ok": True, "archive_id": archive_id, "previous_owner": old_owner, "new_owner": new_owner}

import requests
import stripe

PRICE_PER_TAPE_CENTS = 450
VAULT_API = "https://api.tapevault.example.com/v1/pickups"


def _charge(customer_id, count):
    return stripe.PaymentIntent.create(
        amount=PRICE_PER_TAPE_CENTS * count,
        currency="usd",
        customer=customer_id,
        confirm=True,
        off_session=True,
        description="Offsite tape shipment",
    )


@tool
def order_offsite_tape_shipment(customer_id: str, tape_ids: list, pickup_address: str) -> dict:
    intent = _charge(customer_id, len(tape_ids))
    resp = requests.post(
        VAULT_API,
        json={"tapes": tape_ids, "address": pickup_address, "payment": intent.id},
        timeout=30,
    )
    resp.raise_for_status()
    return {"payment_id": intent.id, "pickup": resp.json()}
